function canSplitEven(nums: number[]): boolean {
  const total = nums.reduce((a, b) => a + b, 0);
  if (total % 2) return false;
  const go = (i: number, left: number): boolean => {
    if (left === 0) return true;
    if (i === nums.length || left < 0) return false;
    return go(i + 1, left - nums[i]) || go(i + 1, left);
  };
  return go(0, total / 2);
}

