function canSplitEven(nums: number[]): boolean {
  const total = nums.reduce((a, b) => a + b, 0);
  if (total % 2) return false;
  const T = total / 2;
  const can = new Array<boolean>(T + 1).fill(false);
  can[0] = true; // the empty pile
  for (const x of nums) {
    for (let s = T; s >= x; s--) if (can[s - x]) can[s] = true; // downward: x used once
    if (can[T]) return true;
  }
  return can[T];
}

