    def canSplitEven(self, nums: List[int]) -> bool:
        total = sum(nums)
        if total % 2:
            return False
        T = total // 2
        can = [True] + [False] * T  # can[0]: the empty pile
        for x in nums:
            for s in range(T, x - 1, -1):  # downward: x used once
                if can[s - x]:
                    can[s] = True
            if can[T]:
                return True
        return can[T]

